use forge_domain :: Transformer ; use crate :: dto :: openai :: Request ; use std :: collections :: HashSet ; use forge_domain :: { Context , ContextMessage , ModelId , Role , TextMessage } ; use pretty_assertions :: assert_eq ; use super :: * ; impl Transformer for SetCache { type Value = Request ; # [doc = " Implements a simple two-breakpoint cache strategy:"] # [doc = " 1. Cache the first message (index 0)"] # [doc = " 2. Cache the last message (index messages.len() - 1)"] # [doc = " 3. Remove cache control from second-to-last message (index"] # [doc = "    messages.len() - 2)"] fn transform (& mut self , mut request : Self :: Value) -> Self :: Value { if let Some (messages) = request . messages . as_mut () { let len = messages . len () ; if len == 0 { return request ; } if len >= 3 && let Some (message) = messages . get_mut (len - 2) && let Some (ref content) = message . content { message . content = Some (content . clone () . cached (false)) ; } if let Some (message) = messages . first_mut () && let Some (ref content) = message . content { message . content = Some (content . clone () . cached (true)) ; } if let Some (message) = messages . last_mut () && let Some (ref content) = message . content { message . content = Some (content . clone () . cached (true)) ; } } request } }